INSERT INTO `kjrt_local_jobboard_convocatoria` (`id`, `code`, `name`, `description`, `brief_description`, `pdf_contenthash`, `pdf_filename`, `startdate`, `enddate`, `status`, `companyid`, `departmentid`, `publicationtype`, `terms`, `allow_multiple_applications`, `max_applications_per_user`, `createdby`, `modifiedby`, `timecreated`, `timemodified`) VALUES
(1, 'CONV-ISER-2026-1', 'Repositorio de Hojas de Vida de Profesores ISER 2026', '<div class=\"convocatoria-description\">\r\n    <h3>Repositorio de Hojas de Vida de Profesores ISER 2026</h3>\r\n\r\n    <div class=\"alert alert-info\">\r\n        <strong>Instituto Superior de Educación Rural - ISER</strong><br>\r\n        Proceso de selección para docentes ocasionales y de cátedra - Vigencia 2025\r\n    </div>\r\n\r\n    <h4>Información General</h4>\r\n    <table class=\"table table-bordered\">\r\n        <tbody><tr><th>Código de Convocatoria</th><td><strong>CONV-ISER-2026-1</strong></td></tr>\r\n        <tr><th>Período Académico</th><td>2026-1</td></tr>\r\n        <tr><th>Período de Inscripción</th><td>17/12/2025 al 11/01/2026</td></tr>\r\n        <tr><th>Total de Vacantes</th><td><strong>503</strong></td></tr>\r\n        <tr><th>Modalidades</th><td>Presencial y A Distancia</td></tr>\r\n        <tr><th>Marco Normativo</th><td>Acuerdo 053 de 29 de noviembre de 2023</td></tr>\r\n        <tr><th>Responsable</th><td>Mauricio Alfredo Zafra Aicardy - Vicerrector Académico</td></tr>\r\n    </tbody></table>\r\n\r\n    <h4>Distribución de Vacantes</h4>\r\n\r\n    <h5>Por Tipo de Vinculación</h5>\r\n    <ul>\r\n        <li><strong>Docente Ocasional Tiempo Completo:</strong> 36 vacantes\r\n            <br><small class=\"text-muted\">Contrato laboral a término fijo por período académico</small></li>\r\n        <li><strong>Docente de Cátedra:</strong> 467 vacantes\r\n            <br><small class=\"text-muted\">Contrato de prestación de servicios por horas</small></li>\r\n    </ul>\r\n\r\n    <h5>Por Facultad</h5>\r\n    <ul>\r\n        <li><strong>FCAS</strong> - Facultad de Ciencias Administrativas y Sociales: 387 perfiles</li>\r\n        <li><strong>FII</strong> - Facultad de Ingenierías e Informática: 101 perfiles</li>\r\n    </ul>\r\n\r\n    <h5>Por Sede / Centro Tutorial</h5>\r\n    <ul>\r\n        <li><strong>Pamplona (Sede Principal):</strong> 143 vacantes</li>\r\n<li><strong>Toledo:</strong> 18 vacantes</li>\r\n<li><strong>El Tarra:</strong> 19 vacantes</li>\r\n<li><strong>Tibú:</strong> 30 vacantes</li>\r\n<li><strong>Sardinata:</strong> 30 vacantes</li>\r\n<li><strong>San Vicente del Chucurí:</strong> 15 vacantes</li>\r\n<li><strong>Santa Rosa del Sur:</strong> 37 vacantes</li>\r\n<li><strong>Saravena:</strong> 29 vacantes</li>\r\n<li><strong>Cúcuta:</strong> 43 vacantes</li>\r\n<li><strong>SALAZAR DE LAS PALMAS:</strong> 22 vacantes</li>\r\n<li><strong>Ocaña:</strong> 30 vacantes</li>\r\n<li><strong>San Pablo (Sur de Bolívar):</strong> 27 vacantes</li>\r\n<li><strong>Cimitarra:</strong> 30 vacantes</li>\r\n<li><strong>Fundación:</strong> 12 vacantes</li>\r\n<li><strong>Pueblo Bello:</strong> 10 vacantes</li>\r\n<li><strong>Tame:</strong> 8 vacantes</li>\r\n\r\n    </ul>\r\n\r\n    <h5>Programas Académicos con Mayor Demanda</h5>\r\n    <ul>\r\n        <li>TECNOLOGÍA EN GESTIÓN EMPRESARIAL: 149 perfiles</li>\r\n<li>TECNOLOGÍA EN GESTIÓN DE MERCADEO: 139 perfiles</li>\r\n<li>TECNOLOGÍA EN GESTIÓN COMUNITARIA: 85 perfiles</li>\r\n<li>Tecnología en Procesos Agroindustriales: 46 perfiles</li>\r\n<li>Todos los Programas de la Facultad de Ingenierías e Informática: 37 perfiles</li>\r\n<li>BIENESTAR INSTITUCIONAL: 15 perfiles</li>\r\n<li>TECNOLOGÍA NE GESTIÓN DE MERCADEO: 12 perfiles</li>\r\n<li>Tecnología en Producción Agropecuaria: 5 perfiles</li>\r\n<li>Tecnología en Gestión de Redes y Sistemas Teleinformáticos: 4 perfiles</li>\r\n<li>Tecnología en Construcción de Obras Civiles: 3 perfiles</li>\r\n\r\n    </ul>\r\n\r\n    <h4>Requisitos Generales (según convocatoria)</h4>\r\n<ol>\r\n<li>Título profesional según perfil específico</li>\r\n<li>Posgrado (según perfil requerido)</li>\r\n<li>Experiencia profesional y/o docente</li>\r\n<li>Certificado de formación en pedagogía para educación superior T y T</li>\r\n<li>Certificado de formación mínimo 20 horas en herramientas tecnológicas</li>\r\n</ol>\r\n\r\n\r\n    <h4>Documentos Requeridos (según convocatoria)</h4>\r\n<ul>\r\n<li>Carta de intención</li>\r\n<li>Hoja de vida formato función pública</li>\r\n<li>Formato Declaración de Bienes y Rentas</li>\r\n<li>Documento de identidad</li>\r\n<li>Libreta militar (si aplica)</li>\r\n<li>Títulos pregrado y posgrado</li>\r\n<li>Tarjeta profesional (si aplica)</li>\r\n<li>Certificaciones complementarias (mínimo 40 horas en últimos 3 años)</li>\r\n<li>Experiencia docente en educación superior</li>\r\n<li>Experiencia profesional</li>\r\n<li>Formación en pedagogía</li>\r\n<li>Formación en TIC (mínimo 20 horas)</li>\r\n<li>RUT actualizado</li>\r\n<li>Antecedentes disciplinarios (Procuraduría)</li>\r\n<li>Antecedentes fiscales (Contraloría)</li>\r\n<li>Antecedentes judiciales (Policía Nacional)</li>\r\n<li>Registro Nacional de Medidas Correctivas</li>\r\n<li>Consulta de Inhabilidades (Ley 1918 de 2018)</li>\r\n<li>REDAM (Registro de Deudores Alimentarios Morosos)</li>\r\n</ul>\r\n\r\n\r\n    <h4>Proceso de Selección</h4>\r\n    <ol>\r\n        <li><strong>Inscripción:</strong> Registro en el sistema y carga de documentos</li>\r\n        <li><strong>Verificación documental:</strong> Revisión de requisitos mínimos</li>\r\n        <li><strong>Evaluación de méritos:</strong> Valoración de formación y experiencia</li>\r\n        <li><strong>Entrevista:</strong> Evaluación de competencias (si aplica)</li>\r\n        <li><strong>Publicación de resultados:</strong> Lista de elegibles</li>\r\n        <li><strong>Vinculación:</strong> Sujeta a disponibilidad presupuestal y según calendarios académicos</li>\r\n    </ol>\r\n\r\n    <h4>Contacto</h4>\r\n<ul>\r\n<li><strong>Instituto Superior de Educación Rural - ISER</strong></li>\r\n<li>Dirección: Vereda Matajira, Km 1 Vía Bucaramanga, Pamplona, Norte de Santander</li>\r\n<li>Teléfono: (607) 5682682</li>\r\n<li>Correo: talento.humano@iser.edu.co</li>\r\n<li>Web: www.iser.edu.co</li>\r\n</ul>\r\n\r\n</div>', NULL, NULL, NULL, 1765947600, 1768193940, 'open', 0, 0, 'public', '<div class=\"convocatoria-terms\">\r\n    <h4>Términos y Condiciones de la Convocatoria</h4>\r\n\r\n    <p>Al registrarse y postularse a esta convocatoria, el aspirante declara bajo la gravedad de juramento y acepta expresamente lo siguiente:</p>\r\n\r\n    <h5>1. Veracidad de la Información</h5>\r\n    <p>Que toda la información consignada en el formulario de inscripción y los documentos adjuntos son verídicos, auténticos y pueden ser verificados por la institución. La presentación de documentos falsos o adulterados causará el rechazo inmediato de la postulación y las acciones legales correspondientes según la legislación colombiana.</p>\r\n\r\n    <h5>2. Autorización de Tratamiento de Datos Personales</h5>\r\n    <p>De conformidad con la Ley 1581 de 2012 (Ley de Protección de Datos Personales), el Decreto 1377 de 2013 y demás normas concordantes, autorizo expresamente al Instituto Superior de Educación Rural - ISER para:</p>\r\n    <ul>\r\n        <li>Recolectar, almacenar, usar, circular y procesar mis datos personales</li>\r\n        <li>Verificar la autenticidad de los documentos presentados ante las entidades correspondientes</li>\r\n        <li>Contactarme por cualquier medio (correo electrónico, teléfono, WhatsApp) para asuntos relacionados con esta convocatoria</li>\r\n        <li>Compartir mi información con entidades de control cuando sea requerido</li>\r\n    </ul>\r\n\r\n    <h5>3. Proceso de Selección</h5>\r\n    <p>Acepto que:</p>\r\n    <ul>\r\n        <li>El proceso de selección se realizará de acuerdo con los criterios establecidos por la institución</li>\r\n        <li>La decisión final de vinculación es discrecional del ISER y no admite recurso alguno</li>\r\n        <li>La inscripción y postulación NO genera ningún derecho ni expectativa de vinculación laboral</li>\r\n        <li>El ISER se reserva el derecho de declarar desierta la convocatoria en cualquier momento</li>\r\n    </ul>\r\n\r\n    <h5>4. Tipo de Vinculación</h5>\r\n    <ul>\r\n        <li><strong>Docente Ocasional Tiempo Completo:</strong> Vinculación mediante contrato laboral a término fijo por el período académico correspondiente, con todas las prestaciones de ley.</li>\r\n        <li><strong>Docente de Cátedra:</strong> Vinculación mediante contrato de prestación de servicios profesionales, remunerado por hora efectivamente dictada. No genera relación laboral.</li>\r\n    </ul>\r\n\r\n    <h5>5. Requisitos de Vinculación</h5>\r\n    <p>En caso de ser seleccionado, la vinculación estará condicionada a:</p>\r\n    <ul>\r\n        <li>Disponibilidad presupuestal de la institución</li>\r\n        <li>Cumplimiento de todos los requisitos legales y documentales</li>\r\n        <li>Aprobación de exámenes médicos ocupacionales</li>\r\n        <li>No estar incurso en inhabilidades o incompatibilidades legales</li>\r\n    </ul>\r\n\r\n    <h5>6. Compromiso del Aspirante</h5>\r\n    <p>Me comprometo a:</p>\r\n    <ul>\r\n        <li>Mantener actualizados mis datos de contacto en el sistema</li>\r\n        <li>Responder oportunamente a las comunicaciones de la institución</li>\r\n        <li>Presentar los documentos originales cuando sean requeridos</li>\r\n        <li>Informar cualquier cambio en mi situación que afecte mi participación</li>\r\n    </ul>\r\n\r\n    <h5>7. Declaración de Inhabilidades</h5>\r\n    <p>Declaro que no me encuentro incurso en ninguna de las causales de inhabilidad o incompatibilidad previstas en la Constitución Política, la Ley 80 de 1993, la Ley 1474 de 2011 y demás normas concordantes para celebrar contratos con entidades públicas.</p>\r\n\r\n    <p class=\"mt-4\"><strong>NOTA IMPORTANTE:</strong> La aceptación de estos términos y condiciones es requisito indispensable para participar en esta convocatoria. Al hacer clic en \"Acepto\" y enviar mi postulación, confirmo haber leído, entendido y aceptado todas las condiciones aquí establecidas.</p>\r\n</div>', 0, 1, 2, 2, 1766098227, 1766162982);
INSERT INTO `kjrt_local_jobboard_doctype` (`id`, `code`, `name`, `description`, `requirements`, `checklistitems`, `externalurl`, `isrequired`, `iserexempted`, `gender_condition`, `age_exemption_threshold`, `profession_exempt`, `conditional_note`, `input_type`, `category`, `defaultmaxagedays`, `sortorder`, `enabled`, `timecreated`, `timemodified`) VALUES
(1, 'carta_intencion', 'Carta de Intención', 'Carta de intención del aspirante', 'Redacte su carta de intención explicando su motivación para aplicar', '[\"Expresa claramente la motivaci\\u00f3n para postularse\",\"Menciona experiencia relevante\",\"Indica disponibilidad y compromiso\",\"Redacci\\u00f3n clara y profesional\"]', '', 1, 0, NULL, NULL, NULL, NULL, 'editor', 'application', NULL, 1, 1, 1766060499, 1766100996),
(2, 'sigep', 'Hoja de Vida Formato Función Pública', 'Hoja de vida actualizada en formato SIGEP II', 'Todos los campos diligenciados, experiencia conforme certificaciones laborales adjuntas, toda experiencia con soporte, debe estar firmado', '[\"Es el formato oficial de SIGEP II\",\"Todos los campos est\\u00e1n diligenciados\",\"Experiencia relacionada corresponde con certificaciones laborales adjuntas\",\"Toda la experiencia relacionada tiene soporte documental\",\"Documento est\\u00e1 firmado\",\"Datos personales son consistentes con otros documentos\"]', 'https://www.funcionpublica.gov.co/web/sigep2', 1, 0, NULL, NULL, NULL, NULL, 'file', 'employment', NULL, 2, 1, 1766060499, NULL),
(3, 'bienes_rentas', 'Formato Declaración de Bienes y Rentas', 'Declaración de bienes y rentas', 'Información de la vigencia inmediatamente anterior, debe estar firmado', '[\"Es el formato oficial de declaraci\\u00f3n\",\"Informaci\\u00f3n corresponde a la vigencia inmediatamente anterior\",\"Documento est\\u00e1 firmado\",\"Fecha de firma es visible\",\"Informaci\\u00f3n es legible\"]', '', 1, 0, NULL, NULL, NULL, NULL, 'file', 'employment', NULL, 3, 1, 1766060499, NULL),
(4, 'cedula', 'Documento de Identidad', 'Fotocopia de cédula de ciudadanía', 'Copia en una sola página, legible', '[\"Documento legible\",\"Copia en una sola p\\u00e1gina (anverso y reverso en la misma hoja)\",\"Contiene foto del titular\",\"N\\u00famero de c\\u00e9dula visible\",\"Nombre completo coincide con datos de postulaci\\u00f3n\"]', '', 1, 1, NULL, NULL, NULL, NULL, 'file', 'identification', NULL, 4, 1, 1766060499, NULL),
(5, 'libreta_militar', 'Libreta Militar', 'Libreta militar o documento que acredite situación militar definida', 'Solo para hombres. Los declarados no aptos, exentos o que hayan superado edad máxima deben presentar certificado provisional', '[\"Es libreta militar O documento que acredite situaci\\u00f3n militar definida\",\"Aplica solo para hombres\",\"Si es declarado no apto, exento o super\\u00f3 edad m\\u00e1xima: certificado provisional\",\"Documento es legible\",\"Nombre coincide con datos de postulaci\\u00f3n\"]', '', 0, 1, 'M', 50, NULL, 'Aplica solo para hombres menores de 50 años', 'file', 'identification', NULL, 5, 1, 1766060499, NULL),
(6, 'titulo_academico', 'Títulos Pregrado y Posgrado', 'Copia de títulos académicos (pregrado, posgrado, especialización, maestría, doctorado)', 'Legibles, completos, debe evidenciarse número de folio, registro y fecha. Títulos extranjeros: Diploma, acta de grado y resolución de convalidación', '[\"Es diploma o acta de grado legible y completo\",\"Nombre del programa es visible\",\"T\\u00edtulo obtenido es claro\",\"N\\u00famero de folio es visible\",\"N\\u00famero de registro es visible\",\"Fecha de grado es visible\",\"Firma de autoridad universitaria presente\",\"Si es t\\u00edtulo extranjero: incluye diploma, acta de grado Y resoluci\\u00f3n de convalidaci\\u00f3n\"]', '', 1, 1, NULL, NULL, NULL, NULL, 'file', 'academic', NULL, 6, 1, 1766060499, NULL),
(7, 'tarjeta_profesional', 'Tarjeta Profesional', 'Fotocopia de tarjeta profesional', 'Legible, vigente. No aplica para licenciados en educación.', '[\"N\\u00famero de tarjeta profesional visible\",\"Nombre del profesional coincide\",\"Consejo profesional que la expide\",\"No est\\u00e1 vencida (si tiene fecha)\"]', '', 0, 1, NULL, NULL, NULL, 'No aplica para Licenciados en Educación', 'file', 'academic', NULL, 7, 1, 1766060499, 1766075651),
(8, 'formacion_complementaria', 'Certificaciones Complementarias', 'Certificados de formación complementaria (mínimo 40 horas)', 'Legibles, completos. Mínimo 40 horas de intensidad por certificado.', '[\"Certificado es legible\",\"Certificado est\\u00e1 completo\",\"Nombre del programa\\/curso es visible\",\"Nombre del participante coincide con postulante\",\"Instituci\\u00f3n que expide es identificable\",\"Duraci\\u00f3n o intensidad horaria especificada (m\\u00ednimo 40 horas)\",\"Fecha de realizaci\\u00f3n o expedici\\u00f3n visible\"]', '', 0, 0, NULL, NULL, NULL, NULL, 'file', 'academic', NULL, 8, 1, 1766060499, NULL),
(9, 'experiencia_docente', 'Experiencia Docente', 'Certificaciones de experiencia en docencia', 'SOLO certificados laborales de experiencia docente. Deben indicar: institución, fechas, carga horaria, programas/asignaturas.', '[\"Es certificado laboral de instituci\\u00f3n educativa\",\"Indica fechas de vinculaci\\u00f3n (desde - hasta)\",\"Especifica cargo docente desempe\\u00f1ado\",\"Indica programas o asignaturas dictadas\",\"Menciona carga horaria o intensidad\",\"Incluye firma de autoridad competente\",\"Tiene fecha de expedici\\u00f3n\"]', '', 0, 1, NULL, NULL, NULL, NULL, 'file', 'employment', NULL, 9, 1, 1766060499, NULL),
(10, 'experiencia_profesional', 'Experiencia Profesional', 'Certificaciones de experiencia laboral profesional', 'SOLO certificados laborales. NO son válidos: contratos, actas de finalización, actos administrativos de nombramientos.', '[\"Es un certificado laboral (NO contrato, acta de finalizaci\\u00f3n o acto administrativo)\",\"Contiene membrete de la empresa\",\"Indica fechas de vinculaci\\u00f3n (desde - hasta)\",\"Especifica cargo desempe\\u00f1ado\",\"Describe funciones o responsabilidades\",\"Incluye firma de autoridad competente\",\"Tiene fecha de expedici\\u00f3n\"]', '', 0, 1, NULL, NULL, NULL, NULL, 'file', 'employment', NULL, 10, 1, 1766060499, NULL),
(11, 'formacion_pedagogia', 'Formación en Pedagogía', 'Certificados de formación en pedagogía, didáctica o enseñanza', 'Certificados de cursos, diplomados o programas en pedagogía, didáctica o metodologías de enseñanza.', '[\"Certificado es legible y completo\",\"Tema del curso es relacionado con pedagog\\u00eda\\/did\\u00e1ctica\",\"Nombre del participante coincide con postulante\",\"Instituci\\u00f3n que expide es identificable\",\"Duraci\\u00f3n o intensidad horaria especificada\",\"Fecha de realizaci\\u00f3n o expedici\\u00f3n visible\"]', '', 0, 0, NULL, NULL, NULL, NULL, 'file', 'academic', NULL, 11, 1, 1766060499, NULL),
(12, 'formacion_tic', 'Formación en TIC', 'Certificados de formación en Tecnologías de la Información y Comunicación', 'Certificados de cursos, diplomados o programas en TIC aplicadas a la educación.', '[\"Certificado es legible y completo\",\"Tema del curso es relacionado con TIC\",\"Nombre del participante coincide con postulante\",\"Instituci\\u00f3n que expide es identificable\",\"Duraci\\u00f3n o intensidad horaria especificada\",\"Fecha de realizaci\\u00f3n o expedici\\u00f3n visible\"]', '', 0, 0, NULL, NULL, NULL, NULL, 'file', 'academic', NULL, 12, 1, 1766060499, NULL),
(13, 'rut', 'RUT Actualizado', 'Registro Único Tributario actualizado', 'Verificar fecha en parte inferior derecha del documento, debe estar actualizado.', '[\"Documento legible\",\"N\\u00famero de NIT\\/RUT visible\",\"Nombre\\/raz\\u00f3n social coincide con datos del postulante\",\"Fecha de actualizaci\\u00f3n visible en parte inferior derecha\",\"Fecha de actualizaci\\u00f3n es reciente\"]', 'https://muisca.dian.gov.co/WebRutMuisca/DefInscripcionRutPortal.faces', 1, 0, NULL, NULL, NULL, NULL, 'file', 'financial', NULL, 13, 1, 1766060499, NULL),
(14, 'antecedentes_disciplinarios', 'Antecedentes Disciplinarios', 'Certificado de la Procuraduría General de la Nación', 'Fecha de expedición no mayor a 30 días recomendado.', '[\"Es certificado oficial de la Procuradur\\u00eda General de la Naci\\u00f3n\",\"Nombre del consultado coincide con postulante\",\"N\\u00famero de c\\u00e9dula coincide\",\"Fecha de expedici\\u00f3n es reciente (preferible <30 d\\u00edas)\",\"C\\u00f3digo de verificaci\\u00f3n visible (si aplica)\",\"Estado de antecedentes es claro\"]', 'https://www.procuraduria.gov.co/portal/Antecedentes.page', 1, 0, NULL, NULL, NULL, NULL, 'file', 'legal', 30, 14, 1, 1766060499, NULL),
(15, 'antecedentes_fiscales', 'Antecedentes Fiscales', 'Certificado de la Contraloría General de la República', 'Fecha de expedición no mayor a 30 días recomendado.', '[\"Es certificado oficial de la Contralor\\u00eda General de la Rep\\u00fablica\",\"Nombre del consultado coincide con postulante\",\"N\\u00famero de c\\u00e9dula coincide\",\"Fecha de expedici\\u00f3n es reciente (preferible <30 d\\u00edas)\",\"C\\u00f3digo de verificaci\\u00f3n visible (si aplica)\",\"Estado de antecedentes es claro\"]', 'https://www.contraloria.gov.co/web/certificados', 1, 0, NULL, NULL, NULL, NULL, 'file', 'legal', 30, 15, 1, 1766060499, NULL),
(16, 'antecedentes_judiciales', 'Antecedentes Judiciales', 'Certificado de la Policía Nacional', 'Fecha de expedición no mayor a 30 días recomendado.', '[\"Es certificado oficial de Polic\\u00eda Nacional\",\"Descargado desde portal oficial\",\"Nombre del consultado coincide\",\"N\\u00famero de c\\u00e9dula coincide\",\"Fecha de expedici\\u00f3n es reciente (<30 d\\u00edas)\",\"Tiene c\\u00f3digo de verificaci\\u00f3n\"]', 'https://antecedentes.policia.gov.co:7005/WebJudicial', 1, 0, NULL, NULL, NULL, NULL, 'file', 'legal', 30, 16, 1, 1766060499, NULL),
(17, 'medidas_correctivas', 'Registro Nacional de Medidas Correctivas', 'Certificado de medidas correctivas de la Policía Nacional', 'Descargado del portal oficial.', '[\"Es certificado oficial de Polic\\u00eda Nacional\",\"Descargado desde portal oficial\",\"Nombre del consultado coincide con postulante\",\"N\\u00famero de c\\u00e9dula coincide\",\"Fecha de expedici\\u00f3n es reciente\",\"Estado es claro\"]', 'https://srvcnpc.policia.gov.co/PSC/frm_cnp_consulta.aspx', 1, 0, NULL, NULL, NULL, NULL, 'file', 'legal', 30, 17, 1, 1766060499, NULL),
(18, 'inhabilidades', 'Consulta de Inhabilidades', 'Consulta de inhabilidades por delitos sexuales contra menores (Ley 1918 de 2018)', 'Certificado descargado del portal oficial.', '[\"Es certificado oficial del Sistema de Informaci\\u00f3n de Inhabilidades\",\"Descargado desde portal oficial\",\"Nombre del consultado coincide con postulante\",\"N\\u00famero de c\\u00e9dula coincide\",\"Fecha de expedici\\u00f3n es reciente\",\"Resultado de consulta es claro\"]', 'https://inhabilidades.policia.gov.co:8080/', 1, 0, NULL, NULL, NULL, NULL, 'file', 'legal', 30, 18, 1, 1766060499, NULL),
(19, 'redam', 'REDAM', 'Registro de Deudores Alimentarios Morosos', 'Registrarse en el portal y descargar certificado.', '[\"Es certificado oficial de REDAM\",\"Descargado desde Carpeta Ciudadana\",\"Nombre del consultado coincide con postulante\",\"N\\u00famero de c\\u00e9dula coincide\",\"Fecha de expedici\\u00f3n es reciente\",\"Estado de registro es claro\"]', 'https://carpetaciudadana.and.gov.co/inicio-de-sesion', 1, 0, NULL, NULL, NULL, NULL, 'file', 'legal', 30, 19, 1, 1766060499, NULL);
