(491, 'BIEN-03', 'BIENESTAR INSTITUCIONAL', '<div class=\"vacancy-description\">\n<div class=\"alert alert-secondary\">\n<strong>Código:</strong> BIEN-03 | <strong>Facultad:</strong> BIENESTAR | <strong>Modalidad:</strong> Presencial\n</div>\n<h4>Programa Académico</h4>\n<p><strong>BIENESTAR INSTITUCIONAL</strong></p>\n<h4>Cursos/Asignaturas a Orientar</h4>\n<ul class=\"list-group list-group-flush mb-3\">\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Actualización de la política de inclusión, crear e implementar la ruta inclusiva institucional</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Diseñar estrategias pedagógicas para la inclusión de las poblaciones vulnerables</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Conformar y dinamizar el comité de inclusión institucional</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Brindar orientaciones y capacitar a los profesores de la institución</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Acompañar a la población priorizadas por la política y garantizar su permanencia</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Orientar curso de electiva sociohumanística</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Apoyo para el desarrollo del plan de acción de Bienestar Institucional</li>\n</ul>\n<h4>Información de la Vinculación</h4>\n<table class=\"table table-sm\">\n<tr><th>Tipo de Vinculación</th><td><span class=\"badge badge-primary\">Ocasional Tiempo Completo</span></td></tr>\n<tr><th>Duración</th><td>4 meses (período académico semestral) - Contrato laboral a término fijo</td></tr>\n<tr><th>Prestaciones</th><td>Seguridad social, prima de servicios, vacaciones (30 días/año)</td></tr>\n<tr><th>Dedicación</th><td>Tiempo completo (40 horas semanales)</td></tr>\n<tr><th>Sede</th><td>Pamplona (Sede Principal)</td></tr>\n<tr><th>Modalidad</th><td>Presencial</td></tr>\n<tr><th>Facultad</th><td>BIENESTAR</td></tr>\n</table>\n</div>\n', 'ocasional_tc', '4 meses (período académico semestral) - Contrato laboral a término fijo', 'Pamplona (Sede Principal)', 'presencial', 'BIENESTAR INSTITUCIONAL', 1, 3, 1, 1, '<div class=\"vacancy-requirements\">\n<h5>Perfil Profesional Requerido</h5>\n<p class=\"lead\">Psicólogo o Trabajador Social o Licenciado en Ciencias Sociales o Sociólogo o Licenciado(a) en educación especial o antropólogo con postgrado, con 2 años de experiencia en contextos de educación inclusiva en instituciones de educación superior</p>\n<h5>Requisitos Mínimos</h5>\n<ul>\n<li>Título profesional universitario acorde al perfil solicitado</li>\n<li>No tener inhabilidades ni incompatibilidades para contratar con el Estado</li>\n<li>Disponibilidad para la sede Pamplona (Sede Principal) en modalidad Presencial</li>\n</ul>\n<h5>Documentos a Presentar</h5>\n<ul>\n<li>Hoja de vida actualizada</li>\n<li>Cédula de ciudadanía</li>\n<li>Títulos académicos (pregrado y posgrado)</li>\n<li>Tarjeta profesional (si aplica)</li>\n<li>Certificaciones de experiencia laboral</li>\n<li>Certificados de antecedentes vigentes</li>\n</ul>\n</div>\n', '<div class=\"vacancy-desirable\">\n<h5>Requisitos Deseables</h5>\n<ul>\n<li>Experiencia docente en educación superior mínimo 1 año</li>\n<li>Publicaciones académicas o investigaciones en el área</li>\n<li>Manejo de herramientas tecnológicas para educación virtual</li>\n<li>Dominio de un segundo idioma (preferiblemente inglés)</li>\n</ul>\n</div>\n', 'published', 'public', NULL, NULL, 2, NULL, 1766098227, NULL),
(492, 'BIEN-04', 'BIENESTAR INSTITUCIONAL', '<div class=\"vacancy-description\">\n<div class=\"alert alert-secondary\">\n<strong>Código:</strong> BIEN-04 | <strong>Facultad:</strong> BIENESTAR | <strong>Modalidad:</strong> Presencial\n</div>\n<h4>Programa Académico</h4>\n<p><strong>BIENESTAR INSTITUCIONAL</strong></p>\n<h4>Cursos/Asignaturas a Orientar</h4>\n<ul class=\"list-group list-group-flush mb-3\">\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Desarrollo de la ruta de prevención de violencia de género</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Desarrollar acciones de acompañamiento psicosocial para la prevención de la violencia de género</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Implementación del plan de acción del protocolo de prevención de violencias basadas en género</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Orientar curso de electiva sociohumanística</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Apoyo para el desarrollo del plan de acción de Bienestar Institucional</li>\n</ul>\n<h4>Información de la Vinculación</h4>\n<table class=\"table table-sm\">\n<tr><th>Tipo de Vinculación</th><td><span class=\"badge badge-info\">Cátedra</span></td></tr>\n<tr><th>Duración</th><td>Semestre académico (16 semanas) - Contrato de prestación de servicios</td></tr>\n<tr><th>Dedicación</th><td>Por horas según programación académica</td></tr>\n<tr><th>Sede</th><td>Pamplona (Sede Principal)</td></tr>\n<tr><th>Modalidad</th><td>Presencial</td></tr>\n<tr><th>Facultad</th><td>BIENESTAR</td></tr>\n</table>\n</div>\n', 'catedra', 'Semestre académico (16 semanas) - Contrato de prestación de servicios por horas', 'Pamplona (Sede Principal)', 'presencial', 'BIENESTAR INSTITUCIONAL', 1, 3, 1, 1, '<div class=\"vacancy-requirements\">\n<h5>Perfil Profesional Requerido</h5>\n<p class=\"lead\">Psicólogo(a), con experiencia mínima de 4 años en contextos de educación superior relacionadas con protocolos para la prevención de violencia de género</p>\n<h5>Requisitos Mínimos</h5>\n<ul>\n<li>Título profesional universitario acorde al perfil solicitado</li>\n<li>No tener inhabilidades ni incompatibilidades para contratar con el Estado</li>\n<li>Disponibilidad para la sede Pamplona (Sede Principal) en modalidad Presencial</li>\n</ul>\n<h5>Documentos a Presentar</h5>\n<ul>\n<li>Hoja de vida actualizada</li>\n<li>Cédula de ciudadanía</li>\n<li>Títulos académicos (pregrado y posgrado)</li>\n<li>Tarjeta profesional (si aplica)</li>\n<li>Certificaciones de experiencia laboral</li>\n<li>Certificados de antecedentes vigentes</li>\n</ul>\n</div>\n', '<div class=\"vacancy-desirable\">\n<h5>Requisitos Deseables</h5>\n<ul>\n<li>Experiencia docente en educación superior mínimo 1 año</li>\n<li>Publicaciones académicas o investigaciones en el área</li>\n<li>Manejo de herramientas tecnológicas para educación virtual</li>\n<li>Dominio de un segundo idioma (preferiblemente inglés)</li>\n</ul>\n</div>\n', 'published', 'public', NULL, NULL, 2, NULL, 1766098227, NULL),
(493, 'BIEN-05', 'BIENESTAR INSTITUCIONAL', '<div class=\"vacancy-description\">\n<div class=\"alert alert-secondary\">\n<strong>Código:</strong> BIEN-05 | <strong>Facultad:</strong> BIENESTAR | <strong>Modalidad:</strong> Presencial\n</div>\n<h4>Programa Académico</h4>\n<p><strong>BIENESTAR INSTITUCIONAL</strong></p>\n<h4>Cursos/Asignaturas a Orientar</h4>\n<ul class=\"list-group list-group-flush mb-3\">\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Orientar cursos de electiva de deportes</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Apoyo para el desarrollo del plan de acción de Bienestar Institucional en el área de deportes</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Entrenar y acompañar a las selecciones institucionales</li>\n</ul>\n<h4>Información de la Vinculación</h4>\n<table class=\"table table-sm\">\n<tr><th>Tipo de Vinculación</th><td><span class=\"badge badge-info\">Cátedra</span></td></tr>\n<tr><th>Duración</th><td>Semestre académico (16 semanas) - Contrato de prestación de servicios</td></tr>\n<tr><th>Dedicación</th><td>Por horas según programación académica</td></tr>\n<tr><th>Sede</th><td>Pamplona (Sede Principal)</td></tr>\n<tr><th>Modalidad</th><td>Presencial</td></tr>\n<tr><th>Facultad</th><td>BIENESTAR</td></tr>\n</table>\n</div>\n', 'catedra', 'Semestre académico (16 semanas) - Contrato de prestación de servicios por horas', 'Pamplona (Sede Principal)', 'presencial', 'BIENESTAR INSTITUCIONAL', 1, 3, 1, 3, '<div class=\"vacancy-requirements\">\n<h5>Perfil Profesional Requerido</h5>\n<p class=\"lead\">Licenciado(a) en educación básica con énfasis en educación física recreación y deportes con experiencia mínima de 2 años en contextos de Educación Superior</p>\n<h5>Requisitos Mínimos</h5>\n<ul>\n<li>Título profesional universitario acorde al perfil solicitado</li>\n<li>No tener inhabilidades ni incompatibilidades para contratar con el Estado</li>\n<li>Disponibilidad para la sede Pamplona (Sede Principal) en modalidad Presencial</li>\n</ul>\n<h5>Documentos a Presentar</h5>\n<ul>\n<li>Hoja de vida actualizada</li>\n<li>Cédula de ciudadanía</li>\n<li>Títulos académicos (pregrado y posgrado)</li>\n<li>Tarjeta profesional (si aplica)</li>\n<li>Certificaciones de experiencia laboral</li>\n<li>Certificados de antecedentes vigentes</li>\n</ul>\n</div>\n', '<div class=\"vacancy-desirable\">\n<h5>Requisitos Deseables</h5>\n<ul>\n<li>Experiencia docente en educación superior mínimo 1 año</li>\n<li>Publicaciones académicas o investigaciones en el área</li>\n<li>Manejo de herramientas tecnológicas para educación virtual</li>\n<li>Dominio de un segundo idioma (preferiblemente inglés)</li>\n</ul>\n</div>\n', 'published', 'public', NULL, NULL, 2, NULL, 1766098227, NULL),
