(497, 'BIEN-09', 'BIENESTAR INSTITUCIONAL', '<div class=\"vacancy-description\">\n<div class=\"alert alert-secondary\">\n<strong>Código:</strong> BIEN-09 | <strong>Facultad:</strong> BIENESTAR | <strong>Modalidad:</strong> Presencial\n</div>\n<h4>Programa Académico</h4>\n<p><strong>BIENESTAR INSTITUCIONAL</strong></p>\n<h4>Cursos/Asignaturas a Orientar</h4>\n<ul class=\"list-group list-group-flush mb-3\">\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Orientar cursos de electiva de Cultura (música)</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Apoyo para el desarrollo del plan de acción de Bienestar Institucional en el área de cultura</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Formar y acompañar a los grupos de musicales institucionales</li>\n</ul>\n<h4>Información de la Vinculación</h4>\n<table class=\"table table-sm\">\n<tr><th>Tipo de Vinculación</th><td><span class=\"badge badge-info\">Cátedra</span></td></tr>\n<tr><th>Duración</th><td>Semestre académico (16 semanas) - Contrato de prestación de servicios</td></tr>\n<tr><th>Dedicación</th><td>Por horas según programación académica</td></tr>\n<tr><th>Sede</th><td>Pamplona (Sede Principal)</td></tr>\n<tr><th>Modalidad</th><td>Presencial</td></tr>\n<tr><th>Facultad</th><td>BIENESTAR</td></tr>\n</table>\n</div>\n', 'catedra', 'Semestre académico (16 semanas) - Contrato de prestación de servicios por horas', 'Pamplona (Sede Principal)', 'presencial', 'BIENESTAR INSTITUCIONAL', 1, 3, 1, 2, '<div class=\"vacancy-requirements\">\n<h5>Perfil Profesional Requerido</h5>\n<p class=\"lead\">Licenciado(a) en educación musical o afines con experiencia de 1 año en educación</p>\n<h5>Requisitos Mínimos</h5>\n<ul>\n<li>Título profesional universitario acorde al perfil solicitado</li>\n<li>No tener inhabilidades ni incompatibilidades para contratar con el Estado</li>\n<li>Disponibilidad para la sede Pamplona (Sede Principal) en modalidad Presencial</li>\n</ul>\n<h5>Documentos a Presentar</h5>\n<ul>\n<li>Hoja de vida actualizada</li>\n<li>Cédula de ciudadanía</li>\n<li>Títulos académicos (pregrado y posgrado)</li>\n<li>Tarjeta profesional (si aplica)</li>\n<li>Certificaciones de experiencia laboral</li>\n<li>Certificados de antecedentes vigentes</li>\n</ul>\n</div>\n', '<div class=\"vacancy-desirable\">\n<h5>Requisitos Deseables</h5>\n<ul>\n<li>Experiencia docente en educación superior mínimo 1 año</li>\n<li>Publicaciones académicas o investigaciones en el área</li>\n<li>Manejo de herramientas tecnológicas para educación virtual</li>\n<li>Dominio de un segundo idioma (preferiblemente inglés)</li>\n</ul>\n</div>\n', 'published', 'public', NULL, NULL, 2, NULL, 1766098227, NULL),
(498, 'BIEN-10', 'BIENESTAR INSTITUCIONAL', '<div class=\"vacancy-description\">\n<div class=\"alert alert-secondary\">\n<strong>Código:</strong> BIEN-10 | <strong>Facultad:</strong> BIENESTAR | <strong>Modalidad:</strong> Presencial\n</div>\n<h4>Programa Académico</h4>\n<p><strong>BIENESTAR INSTITUCIONAL</strong></p>\n<h4>Cursos/Asignaturas a Orientar</h4>\n<ul class=\"list-group list-group-flush mb-3\">\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Acompañamiento psicosocial a estudiantes, docentes y administrativos que requieran los servicios de Bienestar institucional</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Acompañamiento a población con enfoque diferencial</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Orientar curso de electiva sociohumanística</li>\n<li class=\"list-group-item\"><i class=\"fa fa-book mr-2\"></i>Apoyo para el desarrollo del plan de acción de Bienestar Institucional en el Centro de Desarrollo Cúcuta</li>\n</ul>\n<h4>Información de la Vinculación</h4>\n<table class=\"table table-sm\">\n<tr><th>Tipo de Vinculación</th><td><span class=\"badge badge-primary\">Ocasional Tiempo Completo</span></td></tr>\n<tr><th>Duración</th><td>4 meses (período académico semestral) - Contrato laboral a término fijo</td></tr>\n<tr><th>Prestaciones</th><td>Seguridad social, prima de servicios, vacaciones (30 días/año)</td></tr>\n<tr><th>Dedicación</th><td>Tiempo completo (40 horas semanales)</td></tr>\n<tr><th>Sede</th><td>Cúcuta</td></tr>\n<tr><th>Modalidad</th><td>Presencial</td></tr>\n<tr><th>Facultad</th><td>BIENESTAR</td></tr>\n</table>\n</div>\n', 'ocasional_tc', '4 meses (período académico semestral) - Contrato laboral a término fijo', 'Cúcuta', 'presencial', 'BIENESTAR INSTITUCIONAL', 3, 8, 1, 1, '<div class=\"vacancy-requirements\">\n<h5>Perfil Profesional Requerido</h5>\n<p class=\"lead\">Psicólogo(a) con postgrado en intervención comunitaria de 4 años experiencia en el área de bienestar en contexto de educación superior y 2 años con experiencia en trabajo con comunidad en condición de vulnerabilidad</p>\n<h5>Requisitos Mínimos</h5>\n<ul>\n<li>Título profesional universitario acorde al perfil solicitado</li>\n<li>No tener inhabilidades ni incompatibilidades para contratar con el Estado</li>\n<li>Disponibilidad para la sede Cúcuta en modalidad Presencial</li>\n</ul>\n<h5>Documentos a Presentar</h5>\n<ul>\n<li>Hoja de vida actualizada</li>\n<li>Cédula de ciudadanía</li>\n<li>Títulos académicos (pregrado y posgrado)</li>\n<li>Tarjeta profesional (si aplica)</li>\n<li>Certificaciones de experiencia laboral</li>\n<li>Certificados de antecedentes vigentes</li>\n</ul>\n</div>\n', '<div class=\"vacancy-desirable\">\n<h5>Requisitos Deseables</h5>\n<ul>\n<li>Experiencia docente en educación superior mínimo 1 año</li>\n<li>Publicaciones académicas o investigaciones en el área</li>\n<li>Manejo de herramientas tecnológicas para educación virtual</li>\n<li>Dominio de un segundo idioma (preferiblemente inglés)</li>\n</ul>\n</div>\n', 'published', 'public', NULL, NULL, 2, NULL, 1766098227, NULL),
